-- 0087_english_exam_vocab: a ready-made English vocabulary set for the words
-- that show up most in TOEIC (~900) and academic IELTS (~6-7): business/office
-- verbs, finance, compliance, academic connectors and high-frequency adjectives.
-- Own deck "TOEIC 900 / IELTS 6-7" under the English subject so it can be
-- studied as one set. One sense + one example per word (use "Generate with AI"
-- on the deck to expand). Idempotent: deck via (subject_id, slug); cards via
-- ux_cards_deck_kind_front (deck_id, kind, lower(front)).

INSERT INTO decks (subject_id, slug, name, description, default_kind, sort_order)
SELECT s.id, 'exam-vocab', 'TOEIC 900 / IELTS 6-7',
       'High-frequency exam vocabulary for TOEIC (~900) and academic IELTS (~6-7): business, finance, academic connectors, key adjectives.',
       'vocab', 5
FROM subjects s WHERE s.slug = 'english'
ON CONFLICT (subject_id, slug) DO NOTHING;

INSERT INTO cards (deck_id, kind, front, payload, source)
SELECT d.id, 'vocab', v.front, v.payload::jsonb, 'seed'
FROM (VALUES
  ('allocate', '{"senses": [{"level": 1, "meaning_en": "to give out for a particular purpose", "meaning_vi": "phân bổ", "example_en": "The manager will allocate the budget across departments.", "example_vi": "Quản lý sẽ phân bổ ngân sách cho các phòng ban."}], "topic": "Business"}'),
  ('appoint', '{"senses": [{"level": 1, "meaning_en": "to officially choose someone for a job", "meaning_vi": "bổ nhiệm", "example_en": "She was appointed as the new regional director.", "example_vi": "Cô ấy được bổ nhiệm làm giám đốc khu vực mới."}], "topic": "Business"}'),
  ('reimburse', '{"senses": [{"level": 1, "meaning_en": "to pay back money someone has spent", "meaning_vi": "hoàn trả, bồi hoàn", "example_en": "The company will reimburse your travel expenses.", "example_vi": "Công ty sẽ hoàn trả chi phí đi lại của bạn."}], "topic": "Business"}'),
