  ('commence', '{"senses": [{"level": 1, "meaning_en": "to begin", "meaning_vi": "bắt đầu, khởi công", "example_en": "Construction will commence in March.", "example_vi": "Việc xây dựng sẽ khởi công vào tháng Ba."}], "topic": "General"}'),
  ('prohibit', '{"senses": [{"level": 1, "meaning_en": "to officially forbid", "meaning_vi": "cấm", "example_en": "Smoking is prohibited in the building.", "example_vi": "Cấm hút thuốc trong toà nhà."}], "topic": "Compliance"}'),
  ('notify', '{"senses": [{"level": 1, "meaning_en": "to formally inform", "meaning_vi": "thông báo", "example_en": "Please notify us of any changes.", "example_vi": "Vui lòng thông báo cho chúng tôi về mọi thay đổi."}], "topic": "Communication"}'),
  ('renowned', '{"senses": [{"level": 1, "meaning_en": "famous and respected", "meaning_vi": "nổi tiếng, lừng danh", "example_en": "He is a renowned economist.", "example_vi": "Ông ấy là một nhà kinh tế nổi tiếng."}], "topic": "Society"}'),
  ('distinct', '{"senses": [{"level": 1, "meaning_en": "clearly different or separate", "meaning_vi": "khác biệt rõ ràng", "example_en": "The two brands have distinct identities.", "example_vi": "Hai thương hiệu có bản sắc khác biệt rõ ràng."}], "topic": "Marketing"}'),
  ('intricate', '{"senses": [{"level": 1, "meaning_en": "very detailed and complicated", "meaning_vi": "phức tạp, tinh vi", "example_en": "The watch has an intricate design.", "example_vi": "Chiếc đồng hồ có thiết kế tinh vi."}], "topic": "Design"}'),
  ('abundant', '{"senses": [{"level": 1, "meaning_en": "present in large quantities", "meaning_vi": "dồi dào, phong phú", "example_en": "The region has abundant natural resources.", "example_vi": "Khu vực này có nguồn tài nguyên dồi dào."}], "topic": "Nature"}'),
  ('scarce', '{"senses": [{"level": 1, "meaning_en": "not enough; in short supply", "meaning_vi": "khan hiếm", "example_en": "Clean water is scarce in that area.", "example_vi": "Nước sạch khan hiếm ở khu vực đó."}], "topic": "Environment"}'),
  ('susceptible', '{"senses": [{"level": 1, "meaning_en": "easily affected or harmed", "meaning_vi": "dễ bị tác động", "example_en": "Older systems are susceptible to attacks.", "example_vi": "Các hệ thống cũ dễ bị tấn công."}], "topic": "Technology"}'),
  ('resilient', '{"senses": [{"level": 1, "meaning_en": "able to recover quickly", "meaning_vi": "kiên cường, phục hồi nhanh", "example_en": "A resilient economy recovers from shocks.", "example_vi": "Một nền kinh tế kiên cường phục hồi sau cú sốc."}], "topic": "Economics"}'),
  ('plausible', '{"senses": [{"level": 1, "meaning_en": "seeming reasonable or probable", "meaning_vi": "hợp lý, có vẻ đúng", "example_en": "That is a plausible explanation.", "example_vi": "Đó là một lời giải thích hợp lý."}], "topic": "Reasoning"}'),
  ('conversely', '{"senses": [{"level": 1, "meaning_en": "in an opposite way", "meaning_vi": "ngược lại", "example_en": "Conversely, demand fell in winter.", "example_vi": "Ngược lại, nhu cầu giảm vào mùa đông."}], "topic": "Connector"}'),
  ('furthermore', '{"senses": [{"level": 1, "meaning_en": "in addition; moreover", "meaning_vi": "hơn nữa", "example_en": "Furthermore, costs were reduced.", "example_vi": "Hơn nữa, chi phí đã được giảm."}], "topic": "Connector"}'),
  ('predominantly', '{"senses": [{"level": 1, "meaning_en": "mainly; for the most part", "meaning_vi": "chủ yếu", "example_en": "The staff are predominantly young.", "example_vi": "Nhân sự chủ yếu là người trẻ."}], "topic": "Academic"}'),
  ('underlying', '{"senses": [{"level": 1, "meaning_en": "hidden but important as a cause", "meaning_vi": "nền tảng, cốt lõi", "example_en": "We must find the underlying cause.", "example_vi": "Chúng ta phải tìm ra nguyên nhân cốt lõi."}], "topic": "Analysis"}'),
  ('discrepancy', '{"senses": [{"level": 1, "meaning_en": "a difference that should not exist", "meaning_vi": "sự chênh lệch, khác biệt", "example_en": "There is a discrepancy in the figures.", "example_vi": "Có một sự chênh lệch trong các con số."}], "topic": "Finance"}'),
  ('compensation', '{"senses": [{"level": 1, "meaning_en": "payment for work or for loss", "meaning_vi": "tiền bồi thường, thù lao", "example_en": "They offered fair compensation.", "example_vi": "Họ đề nghị mức bồi thường hợp lý."}], "topic": "HR"}')
) AS v(front, payload)
JOIN decks d ON d.slug = 'exam-vocab'
JOIN subjects s ON s.id = d.subject_id AND s.slug = 'english'
ON CONFLICT (deck_id, kind, lower(front)) DO NOTHING;
